using namespace std;

typedef long long ll;
typedef vector<int> vi;

bool f(int x, int y, int z)
{
    if (y > 12)
        return false;
    if (x > 31)
        return false;

    if (y == 3)
    {
        if (z % 4 == 0 && x > 29)
            return false;
        if (z % 4 != 0 && x > 28)
            return false;
    }

    if (y != 3)
    {
        if (y < 7 && y % 2 == 0 && x == 31)
            return false;
        if (y > 7 && y % 2 == 1 && x == 31)
            return false;
    }

    return true;
}

