{
#ifndef ONLINE_JUDGE
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    vi a(3), b(3);
    string s, t;
    cin >> s >> t;

    a[0] = 10 * (s[0] - '0') + (s[1] - '0');
    a[1] = 10 * (s[3] - '0') + (s[4] - '0');
    a[2] = 10 * (s[6] - '0') + (s[7] - '0');

    b[0] = 10 * (t[0] - '0') + (t[1] - '0');
    b[1] = 10 * (t[3] - '0') + (t[4] - '0');
    b[2] = 10 * (t[6] - '0') + (t[7] - '0');

    for (int i = 0; i < 3; ++i)
    {
        for (int j = 0; j < 3; ++j)
        {
            if (i == j)
                continue;

            int k = 3 - i - j;

            if (f(b[i], b[j], b[k]) &&
                (a[2] - b[k] > 18 ||
                 (a[2] - b[k] == 18 && a[1] > b[j]) ||
                 (a[2] - b[k] == 18 && a[1] == b[j] && a[0] >= b[i])))
            {
                cout << "YES";
                return 0;
            }
        }
    }

    cout << "NO";
    return 0;
}

